INSERT INTO `settings` (`id`, `key`, `value`, `label`, `type`, `description`, `updated_by`, `created_at`, `updated_at`) VALUES
(1, 'scale_amounts', '0', 'Scale Amount Display', 'boolean', 'When ON, all amounts are divided by 100 for display. Example: ₹1,45,000 stored → ₹1,450.00 shown. The stored value in the database is never changed.', 1, '2026-05-12 11:28:48', '2026-05-22 13:12:37'),
(2, 'company_name', 'Aman Traders', 'Company Name', 'text', 'Shown on printed reports and PDF headers.', 1, '2026-05-12 11:28:48', '2026-05-22 13:12:37'),
(3, 'financial_year_start', '04-01', 'Financial Year Start', 'text', 'Format: MM-DD. Default is April 1 (04-01) for Indian financial year.', 1, '2026-05-12 11:28:48', '2026-05-22 13:12:37'),
(4, 'allow_customer_purge', '1', 'Allow Permanent Customer Purge', 'boolean', 'When ON, Super Admin can permanently and irreversibly delete a customer and all their transaction history. This is intended only for ended relationships where data must be completely removed.', 1, '2026-05-12 11:28:48', '2026-05-22 13:12:37'),
(5, 'allow_transaction_edit', '1', 'Allow Edit & Delete Transactions', 'boolean', 'When OFF, no one can edit or delete existing transactions. Useful for locking a closed financial period. Super Admin is also restricted.', 1, '2026-05-12 11:28:48', '2026-05-22 13:12:37');
